	title 'QD Polys             GS ROM 2.0'*****************************************************************			   **              POLYS		   **			   **********************************************************************************************************************************			   **	Copyright (C) 1985-1987	   **	All Rights Reserved		   **	Apple Computer, Inc.	   **			   *****************************************************************	string asis	blanks off	include 'all.macros'	include ':QDEquates:qd.data.asm'	INCLUDE ':QDEquates:core.globals1'	INCLUDE ':QDEquates:core.globals2'	INCLUDE ':QDEquates:region.equs'	INCLUDE ':QDEquates:rect.equs'	INCLUDE ':QDEquates:slab.equs';-----------------------------------------------;;   Imported addresses;;-----------------------------------------------	IMPORT BusyEC0	IMPORT BusyEC12	IMPORT BusyEC8	IMPORT BusyErr0	IMPORT BusyErr4	IMPORT BusyErr8	IMPORT DeRefA	IMPORT DerefB	IMPORT LocalMapPoint	IMPORT QDStart	IMPORT RetrieveRects	IMPORT SpecialNewHandle	IMPORT TestGPs	IMPORT UnlockA	IMPORT UnlockB	IMPORT oErrOut4;-----------------------------------------------;;   Forward addresses and entries;;-----------------------------------------------	ENTRY CallPoly	ENTRY EPoly	ENTRY FPoly	ENTRY FrPoly	ENTRY FrameAPoly	ENTRY IPoly	ENTRY JoinPoly	ENTRY KillPolyRegion	ENTRY MakePolyRegion	ENTRY PPoly	ENTRY PolyCheckPenVis	ENTRY RepRgnSave	ENTRY SaveRgnSave;                COPY polys/draw************************************************************* FramePoly  (r : Poly)******************************************************************	EXPORT FramePolyFramePoly	PROC*              using PicInfo	ldx #FrameVerb	bra JoinPoly	ENDP****************************************************************** PaintPoly    (r :	Poly)******************************************************************	EXPORT PaintPolyPaintPoly	PROC*              using PicInfo	ldx #PaintVerb	bra JoinPoly	ENDP****************************************************************** ErasePoly    (r :	Poly)******************************************************************	EXPORT ErasePolyErasePoly	PROC*              using PicInfo	ldx #EraseVerb	bra JoinPoly	ENDP****************************************************************** InvertPoly   (r :	Poly)******************************************************************	EXPORT InvertPolyInvertPoly	PROC*              using PicInfo	ldx #InvertVerb;              let this one fall into JoinPoly	ENDP****************************************************************** JoinPoly** Frame, Paint, Erase and Invert Poly all use this common* code by branching	here with the verb in x register.*****************************************************************	EXPORT JoinPolyJoinPoly	PROCOrigD	equ 1RTL1	equ OrigD+2RTL2	equ RTL1+3PolyHandle	equ RTL2+3	jsr QDStart	; preserves x register	lda PolyHandle,s	sta RgnHandleA	lda PolyHandle+2,s	sta RgnHandleA+2	jsl CallPoly	; verb already in x	tax	; error comes back in x	jmp BusyErr4	ENDP****************************************************************** FillPoly     (r :	Poly; p : pattern)******************************************************************	EXPORT FillPolyFillPoly	PROC*              using PicInfo*              using E0VectorsOrigDiPoly	equ 1RTL1	equ OrigDiPoly+2RTL2	equ RTL1+3PatPtr	equ RTL2+3PolyHandle	equ PatPtr+4	jsr QDStart	jsl UserPat2ZP	lda PolyHandle,s	sta RgnHandleA	lda PolyHandle+2,s	sta RgnHandleA+2	ldx #FillVerb	jsl CallPoly	tax	jmp BusyErr8	ENDP****************************************************************** CallPoly** This routine is jumped (or branched) to by the* entry points after the graf verb is loaded into the* x register.** Zero page is already switched in by the time it gets here.*****************************************************************	EXPORT CallPolyCallPoly	PROC*              using CoreDATA*              using PicInfo*              using QDProcs*              using E0Vectors	stx DrawVerb	jsr TestGPs	; if there is a gp pointer	bcs UseLocal	jml StdPolyUseLocal	phb	; put extra byte on	stack	ldy #o_stdPoly	; get adr of new Poly routine	lda [temp],y	; put on stack	pha	iny	; get bytes 2 and 3	lda [temp],y	sta 2,s	; store middle byte	twice	rtl	; call it	ENDP****************************************************************** StdPoly** Common Polyangle routine that is central point for* all Polyangle drawing routines.** When control gets	here, all inputs are on zero page.*       ThePoly handle is in RgnHandleA*       ThePat (if any) is in TheFillPat*       WhatToDo is	in DrawVerb*****************************************************************	EXPORT iStdPolyiStdPoly	PROC*              using CoreDATA*              using PicInfo*              using QDProcs*              using E0Vectors	lda #PolyNoun	;	jsl PutPictStuff	; inputs on zp and in a-reg	bcc NoPicError	rtl	; return errorNoPicError		; 	lda DrawVerb	; put verb in a	beq FrPolyNotFrame	dec a	asl a	tax	jmp (DoPolyTable,x)DoPolyTable		; 	DC.W PPoly	DC.W EPoly	DC.W IPoly	DC.W FPoly	ENDP****************************************************************** FrPoly** Change History* 7/23/87      GCP	   Removed check for pen visibility.*	   Returns error from FrameAPoly*****************************************************************	EXPORT FrPolyFrPoly	PROC*              using E0Vectors	lda RgnHandleA	ldx RgnHandleA+2	jsr FrameAPoly	ENDP****************************************************************** PPoly** Change history* 7/23/87      GCP	   Now calls PolyCheckPenVis not CheckPenVis*	   Replaced oops with bcs RepRgnSave*****************************************************************	EXPORT PPolyPPoly	PROC*              using E0Vectors	jsr PolyCheckPenVis	; don't come back unless visible	jsr SaveRgnSave	jsr MakePolyRegion	; make the temp region	bcs RepRgnSave	; error so quit.	jsl v_PRgn	pha	; save error code	jsr KillPolyRegion	; get rid of temp region	pla	; get error code back	bra RepRgnSave	ENDP****************************************************************** EPoly** Change History* 7/23/87      GCP	   Now calls PolyCheckPenVis not CheckPenVis*	   Replaced oops with bcs RepRgnSave*****************************************************************	EXPORT EPolyEPoly	PROC*              using CoreDATA*              using PenModeDATA*              using E0Vectors	jsr PolyCheckPenVis	; don't come back unless visible	jsr SaveRgnSave	jsr MakePolyRegion	bcs RepRgnSave	jsl v_ERgn	pha	jsr KillPolyRegion	pla	bra RepRgnSave	ENDP****************************************************************** IPoly** Change History* 7/23/87      GCP	   Now calls PolyCheckPenVis not CheckPenVis*	   Replaced oops with bcs RepRgnSave******************************************************************	EXPORT IPolyIPoly	PROC*              using CoreDATA*              using PenModeDATA*              using E0Vectors	jsr PolyCheckPenVis	; don't come back unless visible	jsr SaveRgnSave	jsr MakePolyRegion	bcs RepRgnSave	jsl v_IRgn	pha	jsr KillPolyRegion	pla	bra RepRgnSave	ENDP****************************************************************** FPoly** Change History* 7/23/87      GCP	   Now checks pen visibility first.*	   Replaced oops with bcs RepRgnSave*	   Falls through to	RepRgnSave******************************************************************	EXPORT FPolyFPoly	PROC*              using CoreData*              using PenModeDATA*              using E0Vectors	jsr PolyCheckPenVis	jsr SaveRgnSave	jsr MakePolyRegion	bcs RepRgnSave	jsl v_FRgn	pha	jsr KillPolyRegion	pla	bra RepRgnSave	ENDP****************************************************************** PolyCheckPenVis** Change history* 7/23/87      GCP	     imported routine from patches.*****************************************************************	EXPORT PolyCheckPenVisPolyCheckPenVis	PROC*              using CoreData*              using PicInfo*              using QDProcs	ldy #o_PnVis	lda [PortRef],y	bpl IsVis	plx	;get rts off stack	lda #0	;clear error code	clc	;clear carry	rtl	;doneIsVis	rts	ENDP****************************************************************** RepRgnSave** Restores the region save field in the	graf port from the stack* while preserving the error code in a-reg.  Carry is set* before final RTL which is the RTL for	the drawing call.*****************************************************************	EXPORT RepRgnSaveRepRgnSave	PROC*              using CoreDATA	tax	ldy #o_PnVis	pla	sta [PortRef],y	ldy #o_RgnSave	pla	sta [PortRef],y	iny	iny	pla	sta [PortRef],y	txa	cmp #1	rtl	; this ends the poly draw call with*		; error (if any) in	a reg	ENDP****************************************************************** SaveRgnSave** Puts the contents	of the RgnSave field of the GrafPort* on the stack above the RTS address and zeros the RgnSave* field in the port.  This way a new region can be opened,* created and closed even if a region is already being saved.*****************************************************************	EXPORT SaveRgnSaveSaveRgnSave	PROC*              using CoreDATA	plx	; put rts adr in x	ldy #o_RgnSave+2	; put the rgnsave on stack and	lda [PortRef],y	; zero that loc in the port	pha	dey	dey	lda [PortRef],y	pha	lda #0	sta [PortRef],y	iny	iny	sta [PortRef],y	ldy #o_PnVis	; Save the pen level and set it	lda [PortRef],y	; to zero so open region will hide it	pha	; close rgn will restore it and let	lda #0	; poly be painted	sta [PortRef],y	phx	; restore rts adr	rts	ENDP****************************************************************** MakePolyRegion** RgnHandleA contains handle to the polygon.  I need to open* a region, draw lines that make up the	points of the polygon,* close the region and put the handle to it in RgnHandleA.** Change History* 7/23/87      GCP	   Added PullCloseAndDie to adjust the stack*	   when NewRgn fails.*****************************************************************	EXPORT MakePolyRegionMakePolyRegion	PROC*              using CoreDATA	pei RgnHandleA+2	; save this on the stack	pei RgnHandleA	_OpenRgn	; open the regions	bcc cont1	plx	; clean stack and quit	plx	rtscont1	pla	plx	jsr FrameAPoly	bcs CloseAndDie	PushLong #0	_NewRgn	bcs PullCloseAndDiecont2	lda 3,s	pha	lda 3,s	pha	_CloseRgn	plx	; preserve any error and status	stx RgnHandleC	; and quit	plx	stx RgnHandleC+2	rtsPullCloseAndDie		; ; pull invalid rgn handle from stack	plx	plx; fall throughCloseAndDie		; 	pha	ldy #o_RgnSave+2	lda [PortRef],y	pha	lda #0	sta [PortRef],y	dey	dey	lda [PortRef],y	pha	lda #0	sta [PortRef],y	_DisposeHandleFinishDie	pla	sec	rts	ENDP****************************************************************** KillPolyRegion** Kills the region whose handle is in RgnHandleC*****************************************************************	EXPORT KillPolyRegionKillPolyRegion	PROC	pei RgnHandleC+2	pei RgnHandleC	_DisposeRgn	rts	ENDP****************************************************************** FrameAPoly** Frames the polygon whose handle is passed in the a and x* registers.** Change History* 7/23/87      GCP	   a reg returns correct error code whe	no error occurs.*****************************************************************	EXPORT FrameAPolyFrameAPoly	PROC	phx	; push handle on stack	pha	pha	; push 2 extra words on stack	pha	phd	; push direct register on stack	tsc	; get stack ptr	tcd	; turn stack to zpOridDirect	equ 1PolyPtr	equ 3PolyHandle	equ 7	ldy #4	; dereference and lock the handle	lda [PolyHandle],y	ora #$8000	sta [PolyHandle],y	lda [PolyHandle]	sta PolyPtr	dey	dey	lda [PolyHandle],y	sta PolyPtr+2	lda #10	cmp [PolyPtr]	; see if there are any points in the	bcs AllDone	tay	; starting with first point move there	lda [PolyPtr],y	tax	iny	iny	lda [PolyPtr],y	iny	iny	phy	; save y on stack	pha	phx	_MoveToPolyLoop	pla	; see if there are any more points	cmp [PolyPtr]	bcs NoMorePoints	tay	; draw a line to the next point	lda [PolyPtr],y	tax	iny	iny	lda [PolyPtr],y	iny	iny	phy	pha	phx	_LineTo	bcc PolyLoop;----------------------------------------------------;; An error occured during lineto so I must clean up; and quit	ply	; get rid of y on stack	pha	; save error code	ldy #4	; unlock the handle	lda [PolyHandle],y	and #$7FFF	sta [PolyHandle],y	pla	; get error back	pld	; clean up the stack	plx	plx	plx	plx	sec	; set carry to signify error	rtsNoMorePoints	ldy #12	; close it up by drawing line back	lda [PolyPtr],y	; to first point.	pha	dey	dey	lda [PolyPtr],y	pha	_LineToAllDone		; 	ldy #4	; unlock the handle	lda [PolyHandle],y	and #$7FFF	sta [PolyHandle],y	pld	; clean up the stack	pla	pla	pla	plx	lda #0	;no error	clc	rts	ENDP;                COPY polys/make****************************************************************** OpenPoly**         Space For	Result  : handle** Checks to see if another poly is already open.  If yes returns* an error. If no then gets a new handle to 256 bytes of mem,* inits that mem with a length of 10 at	beginning and zero* bounding box.*****************************************************************	EXPORT OpenPolyOpenPoly	PROC*              using CoreDATA*              using ErrorDATAOrigDirect	equ 1RTL1Adr	equ OrigDirect+2RTL2Adr	equ RTL1Adr+3ResultH	equ RTL2Adr+3	jsr QDStart	ldy #o_PolySave	lda [PortRef],y	iny	iny	ora [PortRef],y	beq continue	ldx #PolyAlreadyOpen	jmp BusyErr0continue		; 	lda #256	ldx UserID	ldy #0	jsr SpecialNewHandle	bcc Cont2	tax	; move error code to x	jmp BusyErr0	; get outcont2		; 	stx RgnHandleA	sty RgnHandleA+2	ldy #o_PolySave	txa	sta [PortRef],y	iny	iny	lda RgnHandleA+2	sta [PortRef],y	jsr DeRefA	lda #10	; put length of 10 in first word	sta [RgnPtrA]	ldy #2	; zero the bounding	box	lda #0ZeroLoop	sta [RgnPtrA],y	iny	iny	cpy #10	bcc ZeroLoop	lda RgnhandleA	; put result handle	on stack	sta ResultH,s	lda RgnHandleA+2	sta ResultH+2,s	jsr UnlockA	; unlock a	_HidePen	jmp BusyEC0	; all done.	ENDP****************************************************************** ClosePoly******************************************************************	EXPORT ClosePolyClosePoly	PROC*              using CoreDATA*              using ErrorDATA	jsr QDStart	ldy #o_PolySave	; get poly handle to zp	lda [PortRef],y	; and zero the poly	save field of	sta RgnHandleA	; graf port.	lda #0	sta [PortRef],y	iny	iny	lda [PortRef],y	sta RgnHandleA+2	lda #0	sta [PortRef],y	lda RgnHandleA	ora RgnHandleA+2	bne cont0	ldx #PolyNotOpen	jmp BusyErr0cont0	jsr DerefA	lda [RgnPtrA]	pea 0	pha	pei RgnHandleA+2	pei RgnHandleA	jsr UnlockA	_SetHandleSize	bcc cont1	tax	jmp BusyErr0cont1		; ;----------------------------------------------------;; Here I scan through the points and; make the bounding	box.;	jsr DerefA	; relock and deref the rgn	lda [RgnPtrA]	; if this is an empty polygon,	cmp #10	; then there is no bounding box	beq NeverMind	ldy #10	; seed the bounding	box with the	lda [RgnPtrA],y	; first point	sta Y1	sta Y2	iny	iny	lda [RgnPtrA],y	sta X1	sta X2	ldy #14	; start with second	point.*		; it is impossible to have a poly that*		; is only 14 long so its okay to check*		; termination of loop at end.BBLoop		; 	lda [RgnPtrA],y	; Get Y value of point	cmp Y1	; compare to upper	bpl Y1Ok	; greater than upper	sta Y1	; less than upper so replace upperY1OK	cmp Y2	; now check bottom	bmi Y2OK	; its less than bottom	sta Y2	; its greater so replace itY2OK	iny	; bump y to get x value	iny	lda [RgnPtrA],y	cmp X1	; compare to left edge	bpl X1OK	; greater than left	sta X1	; less than left so	replaceX1OK	cmp X2	; compare to right edge	bmi X2OK	; less than right	sta X2	; greater than right so replaceX2OK	iny	; bump y again	iny	tya	; compare to poly size	cmp [RgnPtrA]	; less, so continue	bcc BBLoop;----------------------------------------------------;; Now bounds is complete, so put it in polygon.;	ldy #2	lda Y1	sta [RgnPtrA],y	lda X1	iny	iny	sta [RgnPtrA],y	lda Y2	iny	iny	sta [RgnPtrA],y	lda X2	iny	iny	sta [RgnPtrA],yNeverMind	jsr UnlockA	_ShowPen	jmp BusyEC0	ENDP****************************************************************** KillPoly**              PolyHandle : handle*** Change History** 25 Feb 87    Steven Glass** Routine used busy	end call even though it did not start* by incrementing the busy flag: result	in net dec of* busy flag.  Now uses non-busy end call.*****************************************************************	EXPORT KillPolyKillPoly	PROC*              using CoreDATA*              using ErrorDATARTL1Adr	equ 1RTL2Adr	equ RTL1Adr+3PolyH	equ RTL2Adr+3	lda PolyH,s	tax	lda PolyH+2,s	pha	phx	_DisposeHandle	tax	jmp oErrOut4	ENDP****************************************************************** OffsetPoly**              PolyHandle : handle*              dh	      : word*              dv	      : word*****************************************************************	EXPORT OffsetPolyOffsetPoly	PROCOrigDirect	equ 1RTL1	equ OrigDirect+2RTL2	equ RTL1+3dV	equ RTL2+3dH	equ dV+2PolyHandle	equ dH+2	jsr QDStart	lda PolyHandle,s	sta RgnHandleA	lda PolyHandle+2,s	sta RgnHandleA+2	jsr DerefA	ldy #2OffsetLoop	lda [RgnPtrA],y	clc	adc dV,s	sta [RgnPtrA],y	iny	iny	lda [RgnPtrA],y	clc	adc dH,s	sta [RgnPtrA],y	iny	iny	tya	cmp [RgnPtrA]	bcc OffsetLoopAllDone	jsr UnlockA	jmp BusyEC8	ENDP****************************************************************** MapPoly**              PolyHandle   : handle*              SrcRect      : rectptr*              DestRect     : rectPtr*****************************************************************	EXPORT MapPolyMapPoly	PROCOrigDirect	equ 1RTL1	equ OrigDirect+2RTL2	equ RTL1+3ToRectPtr	equ RTL2+3FromRectPtr	equ ToRectPtr+4PolyHandle	equ FromRectPtr+4*              using E0Vectors	jsr QDStart	jsr RetrieveRects	; get the rects where they're neede	jsl >SetScaleAndMap	; set up the mapping values	lda PolyHandle,s	; get the poly handle into B	sta RgnHandleB	lda PolyHandle+2,s	sta RgnHandleB+2	jsr DerefB	; lock and deref the poly	PushWord #2	; put starting point on stackMapLoop	lda 1,s	; get current offset in poly	cmp [RgnPtrB]	; compare to size of polygon	bcs AllDone	; if greater than or equal then done	tay	; otherwise put this in y and map the	jsr LocalMapPoint	; point that it points to	lda 1,s	; now bump this pointer by 4 and	clc	; continue the loop.	adc #4	sta 1,s	bra MapLoopAllDone	pla	; clear the counter	off the stack	jsr UnlockB	; unlock the polygon	jmp BusyEC12	; goodbye.	ENDP****************************************************************** AddToPoly** Internal routine to determine if we are save in the process* of defining a polygon.  If we are, then we add the point* in Y2,X2 to the polygon definition.** Modifications:**    April 7, 1986	   Zeros accumulator and clc's carry if no*	   error on exit.  returns errors from*	   memmgr calls.**    May 2, 1986	   Checks to see if	open/close can handle*	   this many points.  If it cannot handle*	   the line, it is ignored and error*	   returned.*****************************************************************	EXPORT iAddToPolyiAddToPoly	PROC*              using CoreDATA*              using ErrorData	ldy #o_PolySave	lda [PortRef],y	sta RgnHandleA	iny	iny	lda [PortRef],y	sta RgnHandleA+2	ora RgnHandleA	bne MustAdd	clc	lda #0	rtlMustAdd		; 	jsr DerefA	; deref the handle to get at data;----------------------------------------------------;; Figure out if open/close rgn can handle this point;; First figure number of point sets this line will; contribute.;;      Num = MinOF (ABS (x2-x1), ABS (y2-y1)) + 1;; except when line is vertical when Num	= 0;	lda x2	sec	sbc x1	bpl NotNegX	eor #$FFFF	inc aNotNegX	sta temp	lda y2	; if line is vertical	sec	; there is not point sets	sbc y1	; added	beq ItWillFit	bpl NotNegY	eor #$FFFF	inc aNotNegY	cmp temp	bcc YisLess	lda tempYisLess	inc a	ldy #2	clc	adc [RgnPtrA],y	sta [RgnPtrA],y;----------------------------------------------------;; Now see how many more it will be to close it; up from here.;	lda [RgnPtrA]	; if this is first point	cmp #10	; don't bother.	beq ItWillFit	ldy #12	lda [RgnPtrA],y	sec	sbc x2	bpl NotNegX2	eor #$FFFF	inc aNotNegX2	sta temp	dey	dey	lda [RgnPtrA],y	sec	sbc y2	bpl NotNegY2	eor #$FFFF	inc aNotNegY2	cmp temp	bcc YisLess2	lda tempYisLess2	inc a	ldy #2	clc	adc [RgnPtrA],y	cmp #$2000-8	bcc ItWillFit	jsr UnlockA	lda #PolyTooBig	; signal error;              sec		; carry already set, save a byte.	rtlItWillFit	PushLong #0	; find the handle size	pei RgnHandleA+2	pei RgnHandleA	_GetHandleSize	bcc GotSize	plx	plx	bra oopsGotSize	pla	; handle size in a	plx	sec	sbc #4	; need room for at least 4 bytes	cmp [RgnPtrA]	bcc TooSmall	beq TooSmallNowAddPoints		; 	lda [RgnPtrA]	; this is offset for next point	cmp #10	bne NotFirst	; if equal to 10 then this is 1st pt	tay	; put in y and add the starting	lda Y1	; point	sta [RgnPtrA],y	iny	iny	lda X1	sta [RgnPtrA],y	iny	iny	tyaNotFirst	tay	; put in y and add ending point of line	lda Y2	sta [RgnPtrA],y	iny	iny	lda X2	sta [RgnPtrA],y	iny	iny	tya	sta [RgnPtrA]	jsr UnlockA	; unlock the handle	and quit	clc	lda #0	rtlTooSmall	clc	; bump by decent amount	adc #256+4	pea 0	; Push the parameters for setting	pha	; handles size on the stack	pei RgnHandleA+2	pei RgnHandleA	jsr UnlockA	; unlock the handle	before making this	_SetHandleSize	; call.	bcs Oops	; an error	jsr DerefA	; relock and deref.	bra NowAddPoints	; now go add the points.Oops		; 	rtl	; if get error just	quit now, can't*		; add any more points	ENDP	END